krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_int32 ret = KRB5_KDC_INVALID_REQUEST;
    krb5_principal server_princ = NULL;
    krb5_data hostname_data = {NULL, 0};
    kdc_realm_t *host_realm = NULL;

    if (!request || !krbtgt_princ || !kdc_active_realm) {
        return KRB5_KDC_ERR_BADOPTION;
    }

    server_princ = request->client;
    if (!server_princ || !server_princ->name.name_string.len) {
        return KRB5_KDC_ERR_BAD_CLIENT;
    }

    if (server_princ->name.name_string.val[server_princ->name.name_string.len - 1] != '\0') {
        return KRB5_KDC_ERR_BAD_SERVER;
    }

    hostname_data = server_princ->name.name_string.val[server_princ->name.name_string.len - 1];
    if (!hostname_data.length || !hostname_data.data) {
        return KRB5_KDC_ERR_BAD_SERVER;
    }

    host_realm = find_realm_by_hostname(hostname_data.data);
    if (!host_realm || !host_realm->realm_name || !host_realm->realm_name->length || !host_realm->realm_name->data) {
        return KRB5_KDC_ERR_REALM_NOT_FOUND;
    }

    ret = construct_krbtgt_principal(krbtgt_princ, host_realm->realm_name, server_princ);
    if (ret != 0) {
        free_krb5_principal(*krbtgt_princ);
        *krbtgt_princ = NULL;
        return ret;
    }

    return KRB5_KDC_ERR_SUCCESS;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_int32 ret = KRB5KDC_ERR_NONE;
    krb5_principal server_princ = NULL;
    krb5_data *hostname = NULL;
    kdc_realm_t *target_realm = NULL;

    /* Check if the request is a referral request */
    if (!request->referral_request) {
        ret = KRB5KDC_ERR_INVALID_REQUEST;
        goto cleanup;
    }

    /* Extract the server principal from the request */
    server_princ = request->server;

    /* Extract the hostname from the server principal */
    hostname = krb5_unparse_name(kdc_active_realm->context, server_princ);
    if (!hostname) {
        ret = KRB5KDC_ERR_NO_HOST_NAME;
        goto cleanup;
    }

    /* Check if the hostname is a valid FQDN */
    if (!krb5_is_fqdn(kdc_active_realm->context, hostname)) {
        ret = KRB5KDC_ERR_INVALID_FQDN;
        goto cleanup;
    }

    /* Find the realm associated with the hostname */
    target_realm = find_realm_by_hostname(kdc_active_realm->context, hostname);
    if (!target_realm) {
        ret = KRB5KDC_ERR_REALM_NOT_FOUND;
        goto cleanup;
    }

    /* Ensure the realm is not empty */
    if (target_realm->realm.length == 0) {
        ret = KRB5KDC_ERR_INVALID_REALM;
        goto cleanup;
    }

    /* Construct the TGT principal */
    ret = krb5_build_principal(kdc_active_realm->context, krbtgt_princ, target_realm->realm.length,
                               target_realm->realm.data, "krbtgt", target_realm->realm.length,
                               target_realm->realm.data, NULL);
    if (ret != KRB5KDC_ERR_NONE) {
        goto cleanup;
    }

cleanup:
    if (hostname) {
        krb5_free_data(kdc_active_realm->context, hostname);
    }
    return ret;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_error_code ret = KRB5KDC_ERR_INTERNAL;
    krb5_data *hostname = NULL;
    kdc_realm_t *target_realm = NULL;
    krb5_principal tgs_princ = NULL;

    if (!request || !krbtgt_princ) {
        return KRB5KDC_ERR_BADOPTION;
    }

    if (krb5_is_referral_request(request) != TRUE) {
        return KRB5KDC_ERR_POLICY;
    }

    ret = krb5_unparse_name(NULL, request->client, &hostname);
    if (ret) {
        goto cleanup;
    }

    if (!krb5_is_fqdn(hostname->data)) {
        ret = KRB5_KDC_PATH_NOT_AVAILABLE;
        goto cleanup;
    }

    target_realm = find_realm_by_hostname(hostname->data);
    if (!target_realm) {
        ret = KRB5_REALM_CANT_RESOLVE;
        goto cleanup;
    }

    if (!target_realm->realm || !target_realm->realm[0]) {
        ret = KRB5_REALM_EMPTY;
        goto cleanup;
    }

    ret = krb5_build_principal_simple(NULL, &tgs_princ, strlen("krbtgt") + 1, "krbtgt", strlen(target_realm->realm), target_realm->realm, 0);
    if (ret) {
        goto cleanup;
    }

    *krbtgt_princ = tgs_princ;
    ret = 0;

cleanup:
    if (hostname) {
        krb5_data_free(hostname);
    }
    if (ret && tgs_princ) {
        krb5_free_principal(NULL, tgs_princ);
    }

    return ret;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_data *hostname = NULL;
    krb5_realm *target_realm = NULL;
    krb5_principal referral_princ = NULL;

    if (!request || !krbtgt_princ) {
        return KRB5KDC_ERR_BADOPTION;
    }

    if (!request->server) {
        return KRB5KDC_ERR_BAD_SERVER;
    }

    ret = krb5_unparse_name(kdc_active_realm->context, request->server, &hostname);
    if (ret) {
        return ret;
    }

    if (!krb5_is_fqdn(kdc_active_realm->context, hostname->data)) {
        ret = KRB5KDC_ERR_REFERRED;
        goto cleanup;
    }

    target_realm = krb5_find_realm_by_hostname(kdc_active_realm->context, hostname->data);
    if (!target_realm) {
        ret = KRB5KDC_ERR_NOT_FOUND;
        goto cleanup;
    }

    if (!target_realm->name || strlen(target_realm->name) == 0) {
        ret = KRB5KDC_ERR_BAD_REALM;
        goto cleanup;
    }

    ret = krb5_build_krbtgt_principal(kdc_active_realm->context, &referral_princ, target_realm->name);
    if (ret) {
        goto cleanup;
    }

    *krbtgt_princ = referral_princ;
    referral_princ = NULL;

cleanup:
    if (hostname) {
        krb5_free_data(kdc_active_realm->context, hostname);
    }
    if (referral_princ) {
        krb5_free_principal(kdc_active_realm->context, referral_princ);
    }

    return ret;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_error_code ret = KRB5_KDC_ERR_SERVICE_UNAVAILABLE;
    krb5_principal *host_realm_princ = NULL;
    krb5_data *hostname = NULL;
    krb5_realm *host_realm = NULL;

    if (!request || !krbtgt_princ || !kdc_active_realm) {
        ret = KRB5_BAD_ARG;
        goto cleanup;
    }

    if (!request->server) {
        ret = KRB5KDC_ERR_NOPOLICY;
        goto cleanup;
    }

    if (krb5_princ_comp(krb5_context, request->server, 0) == NULL) {
        ret = KRB5KDC_ERR_BADOPTION;
        goto cleanup;
    }

    hostname = krb5_princ_component(krb5_context, request->server, 0);
    if (!hostname || !hostname->length) {
        ret = KRB5KDC_ERR_REALM_CANT;
        goto cleanup;
    }

    ret = krb5_build_principal(krb5_context, &host_realm_princ, 0, 0, NULL, 0, hostname, 0, NULL);
    if (ret != 0) {
        goto cleanup;
    }

    host_realm = krb5_realmname(krb5_context, host_realm_princ);
    if (!host_realm || host_realm->length == 0) {
        ret = KRB5KDC_ERR_REALM_CANT;
        goto cleanup;
    }

    if (strcmp(krb5_realmname(krb5_context, kdc_active_realm), host_realm->data) == 0) {
        ret = KRB5KDC_ERR_WRONG_REALM;
        goto cleanup;
    }

    ret = krb5_build_principal(krb5_context, krbtgt_princ, host_realm->length, host_realm->data, NULL, 1, "krbtgt", 0, hostname, 0, NULL);
    if (ret != 0) {
        goto cleanup;
    }

    ret = 0;

cleanup:
    if (host_realm_princ) {
        krb5_free_principal(krb5_context, host_realm_princ);
    }
    if (hostname) {
        krb5_data_free(hostname);
    }

    return ret;
}
